125	type Entry =
126	  | { type: "Stroke"; tile: Tile; object: Stroke; frame: StrokeFrame; ink: StrokeInk }
127	  | { type: "Shape"; tile: Tile; object: Shape; start: Point; end: Point }
128	  | { type: "Sticky"; tile: Tile; object: Sticky; lines: string[] }
129	  | { type: "Text"; tile: Tile; object: Text; lines: string[]; ink: BBox };
130	
131	const isWritable = (entry: Entry | undefined): entry is Entry & { object: Sticky | Text } =>
132	  entry?.type === "Sticky" || entry?.type === "Text";
133	
134	const hits = (entry: Entry, world: Point, zoom: number): boolean => {
135	  if (entry.type === "Text") return hitsFrame({ bbox: entry.ink }, world, zoom);
136	  if (entry.type === "Sticky") return hitsFrame(entry.object, world, zoom);
137	  return entry.type === "Stroke"
138	    ? hitsStroke(entry.tile, entry.object, world, zoom)
139	    : hitsShape(entry.tile, entry.object, world, zoom);
140	};
141	
142	const translate = (
143	  entry: Entry,
144	  dx: number,
145	  dy: number,
146	  measureAt: (px: number) => Measure,
147	): StoredObject | undefined => {
148	  if (entry.type === "Sticky") return translateSticky(entry.object, dx, dy);
149	  if (entry.type === "Text") return translateText(entry.tile, entry.object, dx, dy, measureAt);
150	  return entry.type === "Stroke"
151	    ? translateStroke(entry.tile, entry.object, dx, dy)
152	    : translateShape(entry.tile, entry.object, dx, dy);
153	};
154	
155	type Drag = { objectId: string; from: Point; dx: number; dy: number };
156	
157	const extent = (entry: Entry): BBox => {
158	  if (entry.type === "Stroke") return strokeExtent(entry.tile, entry.object);
159	  if (isWritable(entry)) return entry.object.bbox;
160	  const { start, end } = entry;
161	  return {
162	    minX: Math.min(start.x, end.x),
163	    minY: Math.min(start.y, end.y),
164	    maxX: Math.max(start.x, end.x),
165	    maxY: Math.max(start.y, end.y),
166	  };
167	};
168	
169	const scale = (
170	  entry: Entry,
171	  by: Scale,
172	  measureAt: (px: number) => Measure,
173	): StoredObject | undefined => {
174	  if (entry.type === "Sticky") return scaleSticky(entry.object, by, measureAt);
175	  if (entry.type === "Text") return scaleText(entry.object, by, measureAt);
176	  return entry.type === "Stroke"
177	    ? scaleStroke(entry.tile, entry.object, by)
178	    : scaleShape(entry.tile, entry.object, by);
179	};
180	
181	const colourOf = (object: Entry["object"]): number => {
182	  if (object.type === "Sticky") return object.background;
183	  return object.type === "Text" ? object.rgb : rgbOf(object);
184	};
185	
186	type Corner = { right: boolean; bottom: boolean };
187	
188	const CORNERS: readonly Corner[] = [
189	  { right: false, bottom: false },
190	  { right: true, bottom: false },
191	  { right: true, bottom: true },
192	  { right: false, bottom: true },
193	];
194	
195	const cornerOf = (box: BBox, { right, bottom }: Corner): Point => ({
196	  x: right ? box.maxX : box.minX,
197	  y: bottom ? box.maxY : box.minY,
198	});
199	
200	type Resize = {
201	  objectId: string;
202	  anchor: Point;
203	  corner: Point;
204	  from: Point;
205	  result: StoredObject | undefined;
206	  preview: Entry | undefined;
207	};
208	
209	const SELECTION_PAD_PX = 4;
210	
211	const paintPreview = (ctx: CanvasRenderingContext2D, entry: Entry, dpr: number): void => {
212	  const fit = previewFit(extent(entry));
213	  const view: Camera = { x: fit.x, y: fit.y, zoom: fit.scale };
214	  const toScreen = (world: Point): Point => worldToScreen(view, world);
215	  const bounds: BBox = { minX: 0, minY: 0, maxX: PREVIEW_WIDTH, maxY: PREVIEW_HEIGHT };
216	  const colour = rgbHex(colourOf(entry.object));
217	  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
218	  ctx.fillStyle = PAPER;
219	  ctx.fillRect(0, 0, PREVIEW_WIDTH, PREVIEW_HEIGHT);
220	  if (entry.type === "Sticky") {
221	    const { bbox } = entry.object;
222	    paintSticky(
223	      ctx,
224	      entry.object,
225	      entry.lines,
226	      {
227	        ...toScreen({ x: bbox.minX, y: bbox.minY }),
228	        width: (bbox.maxX - bbox.minX) * view.zoom,
229	        height: (bbox.maxY - bbox.minY) * view.zoom,
230	      },
231	      view.zoom,
232	      true,
233	      bounds,
234	    );
235	    return;
236	  }
237	  if (entry.type === "Text") {
238	    const { bbox } = entry.object;
239	    paintText(ctx, entry.object, entry.lines, toScreen({ x: bbox.minX, y: bbox.minY }), view.zoom);
240	    return;
241	  }
242	  if (entry.type === "Shape") {
243	    paintShape(
244	      ctx,
245	      shapeScreenInk(shapeLook(entry.object), entry.start, entry.end, toScreen, view.zoom),
246	      colour,
247	    );
248	    return;
249	  }
250	  const { origin } = entry.frame;
251	  const inkScale = entry.frame.scale * view.zoom * dpr;
252	  ctx.setTransform(
253	    inkScale,
254	    0,
255	    0,
256	    inkScale,
257	    (origin.x - view.x) * view.zoom * dpr,
258	    (origin.y - view.y) * view.zoom * dpr,
259	  );
260	  paintInk(ctx, entry.ink, colour);
261	};
