287	type RemoteCursor = { x: number; y: number; name: string; colour: string };
288	
289	const remoteCursor = (clientId: number, state: unknown): RemoteCursor | undefined => {
290	  if (typeof state !== "object" || state === null) return undefined;
291	  const { cursor, user } = state as Record<string, unknown>;
292	  if (typeof cursor !== "object" || cursor === null) return undefined;
293	  const { x, y } = cursor as Record<string, unknown>;
294	  if (typeof x !== "number" || typeof y !== "number") return undefined;
295	  const name = displayName(
296	    typeof user === "object" && user !== null ? (user as { name?: unknown }).name : undefined,
297	  );
298	  return { x, y, name, colour: presenceColour(clientId) };
299	};
