301	export const PAPER = "#fbfaf7";
302	
303	const DEFAULT_CAMERA: Camera = { x: 0, y: 0, zoom: 1 };
304	
305	const isCamera = (value: unknown): value is Camera => {
306	  if (typeof value !== "object" || value === null) return false;
307	  const { x, y, zoom } = value as Record<string, unknown>;
308	  return (
309	    typeof x === "number" &&
310	    typeof y === "number" &&
311	    typeof zoom === "number" &&
312	    Number.isFinite(x) &&
313	    Number.isFinite(y) &&
314	    zoom > 0 &&
315	    Number.isFinite(zoom)
316	  );
317	};
