319	const cameraKey = (boardId: string): string => `stallion:camera:${boardId}`;
320	
321	const loadCamera = (boardId: string): Camera => {
322	  try {
323	    const parsed: unknown = JSON.parse(localStorage.getItem(cameraKey(boardId)) ?? "null");
324	    return isCamera(parsed) ? parsed : DEFAULT_CAMERA;
325	  } catch {
326	    return DEFAULT_CAMERA;
327	  }
328	};
