330	const saveCamera = (boardId: string, camera: Camera): void => {
331	  try {
332	    localStorage.setItem(cameraKey(boardId), JSON.stringify(camera));
333	  } catch {
334	    // Camera position is a per-viewer convenience; losing it only recentres the board.
335	  }
336	};
