355	const sameEdit = (a: TextEdit | undefined, b: TextEdit | undefined): boolean =>
356	  a === b ||
357	  (a !== undefined &&
358	    b !== undefined &&
359	    a.objectId === b.objectId &&
360	    a.ink === b.ink &&
361	    a.background === b.background &&
362	    a.left === b.left &&
363	    a.top === b.top &&
364	    a.width === b.width &&
365	    a.height === b.height &&
366	    a.fontPx === b.fontPx);
