368	export type Surface = {
369	  zoomToLevel(level: number): void;
370	  follow(clientId: number | undefined): void;
371	  editText(text: string): void;
372	  levelObjects(level: number): LevelObjects;
373	  preview(objectId: string): string | undefined;
374	  jumpTo(objectId: string): void;
375	  highlight(objectId: string | undefined): void;
376	  finishEdit(): void;
377	  panBy(dx: number, dy: number): void;
