381	const NO_PRESENCE: Presence = { peers: [], following: undefined };
382	
383	export function createSurface(
384	  canvas: HTMLCanvasElement,
385	  boardId: string,
386	  source: DrawingSource,
387	  currentTool: () => Tool,
388	  onView: (view: SurfaceView) => void = () => undefined,
389	  onCommit: () => void = () => undefined,
390	  onPresence: (presence: Presence) => void = () => undefined,
391	  onEdit: (edit: TextEdit | undefined) => void = () => undefined,
392	): Surface {
393	  const context = canvas.getContext("2d");
394	  if (!context) throw new Error("This browser cannot create a 2D canvas context.");
395	  const ctx = context;
396	
397	  const entries = new Map<string, Entry>();
398	  let ordered: Entry[] = [];
399	  let camera = loadCamera(boardId);
400	  let draft: Draft | undefined;
401	  let shapeDraft: ShapeDraft | undefined;
402	  let eraser: Point | undefined;
403	  let selected: string | undefined;
404	  let drag: Drag | undefined;
405	  let resizing: Resize | undefined;
406	  let press: { mode: "Sticky" | "Text"; point: Point; secondary: boolean } | undefined;
407	  let editing: { objectId: string; text: string; pending: Entry | undefined } | undefined;
408	  let reportedEdit: TextEdit | undefined;
409	  let spaceDown = false;
410	  let frame = 0;
411	  let settleTimer: ReturnType<typeof setTimeout> | undefined;
412	  let pendingTimer: ReturnType<typeof setTimeout> | undefined;
413	  let cursors: RemoteCursor[] = [];
414	  let cursorSentAt = 0;
415	  let animation = 0;
416	  let reported: SurfaceView | undefined;
417	  let dragButton = 0;
418	  let presence = NO_PRESENCE;
419	  let published: Viewport | undefined;
420	  let publishedAt = Number.NEGATIVE_INFINITY;
421	  let publishTimer: ReturnType<typeof setTimeout> | undefined;
422	  const input = createInput();
423	  const awareness = source.awareness;
424	  const publisher = awareness && createInkPublisher(awareness);
425	  const reader = createInkReader();
426	  const landed = new Set<string>();
427	  let inks: LiveInk[] = [];
428	  let hover: Point | undefined;
429	  let candidates: Candidate[] = [];
430	  let rippleSince: number | undefined;
431	  let previewed: string | undefined;
432	  const previews = new WeakMap<Entry, string>();
433	
434	  const size = () => ({ width: canvas.clientWidth, height: canvas.clientHeight });
435	
436	  const screenBounds = (): BBox => ({
437	    minX: 0,
438	    minY: 0,
439	    maxX: canvas.clientWidth,
440	    maxY: canvas.clientHeight,
441	  });
442	
443	  const onScreen = (bbox: BBox, { dx, dy }: { dx: number; dy: number }): BBox => {
444	    const topLeft = worldToScreen(camera, { x: bbox.minX + dx, y: bbox.minY + dy });
445	    const bottomRight = worldToScreen(camera, { x: bbox.maxX + dx, y: bbox.maxY + dy });
446	    return { minX: topLeft.x, minY: topLeft.y, maxX: bottomRight.x, maxY: bottomRight.y };
447	  };
448	
449	  const render = () => {
450	    frame = 0;
451	    const dpr = window.devicePixelRatio || 1;
452	    const { width, height } = size();
453	    ctx.setTransform(1, 0, 0, 1, 0, 0);
454	    ctx.fillStyle = PAPER;
455	    ctx.fillRect(0, 0, canvas.width, canvas.height);
456	    ctx.save();
457	    ctx.beginPath();
458	    ctx.rect(0, 0, canvas.width, canvas.height);
459	    ctx.clip();
460	    const screen = screenBounds();
461	    const device: BBox = { minX: 0, minY: 0, maxX: canvas.width, maxY: canvas.height };
462	    const view = viewBounds(camera, width, height);
463	    const toDevice = (world: Point): Point => ({
464	      x: (world.x - camera.x) * camera.zoom * dpr,
465	      y: (world.y - camera.y) * camera.zoom * dpr,
466	    });
467	    const markers: Marker[] = [];
468	    const locating = currentTool().mode === "Select";
469	    candidates = [];
470	    for (const original of ordered) {
471	      const resized =
472	        resizing?.objectId === original.object.objectId ? resizing.preview : undefined;
473	      const entry = resized ?? original;
474	      const dragged = drag?.objectId === entry.object.objectId ? drag : undefined;
475	      const culled = dragged || resized ? "Draw" : cull(entry.object.bbox, view, camera.zoom);
476	      if (culled === "Skip") continue;
477	      const colour = rgbHex(colourOf(entry.object));
478	      const radius =
479	        locating && !dragged && !resized && screenRadius(entry.object.bbox, camera.zoom);
480	      if (radius && isSmall(radius)) {
481	        const centre = worldToScreen(camera, bboxCentre(entry.object.bbox));
482	        candidates.push({ ...centre, radius, style: colour });
483	      }
484	      if (culled === "Marker") {
485	        markers.push({ ...toDevice(bboxCentre(entry.object.bbox)), style: colour });
486	        continue;
487	      }
488	      const offset = dragged ?? { dx: 0, dy: 0 };
489	      const oversized = exceeds(onScreen(entry.object.bbox, offset), screen);
490	      if (entry.type === "Sticky") {
491	        const { bbox } = entry.object;
492	        const topLeft = worldToScreen(camera, {
493	          x: bbox.minX + offset.dx,
494	          y: bbox.minY + offset.dy,
495	        });
496	        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
497	        paintSticky(
498	          ctx,
499	          entry.object,
500	          entry.lines,
501	          {
502	            ...topLeft,
503	            width: (bbox.maxX - bbox.minX) * camera.zoom,
504	            height: (bbox.maxY - bbox.minY) * camera.zoom,
505	          },
506	          camera.zoom,
507	          editing?.objectId !== entry.object.objectId,
508	          screen,
509	        );
510	        continue;
511	      }
512	      if (entry.type === "Text") {
513	        if (editing?.objectId === entry.object.objectId) continue;
514	        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
515	        paintText(
516	          ctx,
517	          entry.object,
518	          entry.lines,
519	          worldToScreen(camera, {
520	            x: entry.object.bbox.minX + offset.dx,
521	            y: entry.object.bbox.minY + offset.dy,
522	          }),
523	          camera.zoom,
524	        );
525	        continue;
526	      }
527	      if (entry.type === "Shape") {
528	        const shift = (world: Point): Point =>
529	          worldToScreen(camera, { x: world.x + offset.dx, y: world.y + offset.dy });
530	        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
531	        paintShape(
532	          ctx,
533	          shapeScreenInk(shapeLook(entry.object), entry.start, entry.end, shift, camera.zoom),
534	          colour,
535	          1,
536	          oversized ? screen : undefined,
537	        );
538	        continue;
539	      }
540	      const { origin } = entry.frame;
541	      const scale = entry.frame.scale * camera.zoom * dpr;
542	      const x = (origin.x + offset.dx - camera.x) * camera.zoom * dpr;
543	      const y = (origin.y + offset.dy - camera.y) * camera.zoom * dpr;
544	      if (oversized) {
545	        ctx.setTransform(1, 0, 0, 1, 0, 0);
546	        paintInk(ctx, entry.ink, colour, 1, { scale, x, y, bounds: device });
547	        continue;
548	      }
549	      ctx.setTransform(scale, 0, 0, scale, x, y);
550	      paintInk(ctx, entry.ink, colour);
551	    }
552	    renderMarkers(
553	      source.hints.current.map((hint) => ({
554	        ...toDevice(bboxCentre(tileBounds(hint))),
555	        style: HINT_GREY,
556	      })),
557	    );
558	    renderMarkers(markers);
559	    if (inks.length > 0) renderInks(dpr);
560	    if (draft && draft.points.length > 0) {
561	      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
562	      paintInk(
563	        ctx,
564	        draftScreenInk(draft, (world) => worldToScreen(camera, world), camera.zoom),
565	        rgbHex(draft.rgb),
566	      );
567	    }
568	    if (shapeDraft) {
569	      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
570	      paintShape(
571	        ctx,
572	        shapeScreenInk(
573	          shapeDraft,
574	          shapeDraft.start,
575	          shapeDraft.end,
576	          (world) => worldToScreen(camera, world),
577	          camera.zoom,
578	        ),
579	        rgbHex(shapeDraft.rgb),
580	      );
581	    }
582	    renderSelection(dpr);
583	    renderLocators(dpr);
584	    renderPreviewed(dpr);
585	    if (cursors.length > 0) renderCursors(dpr);
586	    ctx.restore();
587	    reportEdit();
588	  };
589	
590	  const editOf = (): TextEdit | undefined => {
591	    if (!editing) return undefined;
592	    const original = entries.get(editing.objectId) ?? editing.pending;
593	    const entry =
594	      resizing?.objectId === editing.objectId && resizing.preview ? resizing.preview : original;
595	    if (!isWritable(entry)) return undefined;
596	    const { dx, dy } = drag?.objectId === editing.objectId ? drag : { dx: 0, dy: 0 };
597	    const { object } = entry;
598	    const { bbox } = object;
599	    const rect = canvas.getBoundingClientRect();
600	    const topLeft = worldToScreen(camera, { x: bbox.minX + dx, y: bbox.minY + dy });
601	    const placement = {
602	      objectId: object.objectId,
603	      text: editing.text,
604	      ink: rgbHex(object.rgb),
605	      left: rect.left + topLeft.x,
606	      top: rect.top + topLeft.y,
607	      width: (bbox.maxX - bbox.minX) * camera.zoom,
608	      height: (bbox.maxY - bbox.minY) * camera.zoom,
609	    };
610	    if (object.type === "Text") {
611	      const font = worldFont(object) * camera.zoom;
612	      return {
613	        ...placement,
614	        label: "Text",
615	        background: "transparent",
616	        fontPx: font,
617	        padPx: 0,
618	        lineHeightPx: font * LINE_HEIGHT,
619	      };
620	    }
621	    const metrics = stickyMetrics(object);
622	    return {
623	      ...placement,
624	      label: "Note text",
625	      background: rgbHex(object.background),
626	      fontPx: metrics.font * camera.zoom,
627	      padPx: metrics.pad * camera.zoom,
628	      lineHeightPx: metrics.lineHeight * camera.zoom,
629	    };
630	  };
631	
632	  const reportEdit = () => {
633	    const next = editOf();
634	    if (sameEdit(reportedEdit, next)) return;
635	    reportedEdit = next;
636	    onEdit(next);
637	  };
638	
639	  const startEdit = (objectId: string, pending?: Entry) => {
640	    if (editing?.objectId === objectId) return;
641	    const entry = entries.get(objectId);
642	    editing = { objectId, text: isWritable(entry) ? entry.object.text : "", pending };
643	    selected = pending ? undefined : objectId;
644	    reportEdit();
645	    requestRender();
646	  };
647	
648	  const commitEdit = (stored: StoredObject | undefined) => {
649	    if (!stored) return;
650	    source.commit(stored);
651	    source.history.checkpoint();
652	    onCommit();
653	  };
654	
655	  const finishText = (entry: Entry | undefined, text: string) => {
656	    if (entry?.type !== "Text" || text === entry.object.text) return;
657	    if (text.trim() === "") {
658	      if (!entries.has(entry.object.objectId)) return;
659	      source.erase(entry.object.objectId);
660	      source.history.checkpoint();
661	      onCommit();
662	      return;
663	    }
664	    commitEdit(withTextContent(entry.tile, entry.object, text, measureAt));
665	  };
666	
667	  const finishEdit = () => {
668	    if (!editing) return;
669	    const { objectId, text, pending } = editing;
670	    editing = undefined;
671	    const entry = entries.get(objectId) ?? pending;
672	    if (entry?.type === "Sticky" && text !== entry.object.text) {
673	      commitEdit(withText(entry.object, text, measureAt));
674	    }
675	    finishText(entry, text);
676	    reportEdit();
677	    requestRender();
678	  };
679	
680	  const placeText = (at: Point, secondary: boolean) => {
681	    const hit = pick(at);
682	    if (hit?.type === "Text") {
683	      startEdit(hit.object.objectId);
684	      return;
685	    }
686	    const tool = currentTool();
687	    const stored = startText(
688	      secondary ? tool.secondary : tool.primary,
689	      camera.zoom,
690	      screenToWorld(camera, at),
691	      measureAt,
692	    );
693	    const pending = stored && entryOf(stored);
694	    if (pending) startEdit(pending.object.objectId, pending);
695	  };
696	
697	  const placeSticky = (press: { point: Point; secondary: boolean }) => {
698	    const hit = pick(press.point);
699	    if (hit?.type === "Sticky") {
700	      startEdit(hit.object.objectId);
701	      return;
702	    }
703	    const tool = currentTool();
704	    const stored = startSticky(
705	      press.secondary ? tool.secondary : tool.primary,
706	      camera.zoom,
707	      screenToWorld(camera, press.point),
708	    );
709	    if (!stored) return;
710	    source.commit(stored);
711	    source.history.checkpoint();
712	    onCommit();
713	    startEdit(stored.object.objectId);
714	  };
715	
716	  const renderMarkers = (markers: Iterable<Marker>) => {
717	    ctx.setTransform(1, 0, 0, 1, 0, 0);
718	    ctx.globalAlpha = MARKER_ALPHA;
719	    for (const marker of dedupeMarkers(markers)) {
720	      ctx.fillStyle = marker.style;
721	      ctx.fillRect(marker.x, marker.y, MARKER_PX, MARKER_PX);
722	    }
