import { openBoard } from "@stallion/client-sync";
import { PALETTE_RGB, PENCIL_PX } from "@stallion/schema";
import { useCallback, useEffect, useRef, useState } from "preact/hooks";
import { boardPath } from "./board-path";
import type { LevelBrowser } from "./level-chip";
import { myBoardsForPage, thumbnailUploader } from "./my-boards";
import { PinPrompt } from "./pin-prompt";
import type { Presence } from "./presence";
import { loadRecents, renameRecent, saveRecents, upsertRecent } from "./recents";
import { useConnectionNotice } from "./reconnect";
import { ReconnectNotice } from "./reconnect-notice";
import { errorMessage, reportLink } from "./report";
import { boardLink, SharePanel } from "./share";
import {
  createSurface,
  type Surface,
  type SurfaceView,
  type TextEdit,
  type Tool,
  type ToolMode,
} from "./surface";
import { type BoardSource, type Connection, openSource, syncUrlFor } from "./sync";
import { openEditor, TextEditor } from "./text-editor";
import { captureThumbnail } from "./thumbnail";
import { type HistoryState, Toolbar } from "./toolbar";
import { loadStyle } from "./toolbar-layout";

const EMPTY_HISTORY: HistoryState = { canUndo: false, canRedo: false };

const INITIAL_VIEW: SurfaceView = { level: 0, contentLevels: [] };

const THUMBNAIL_DELAY_MS = 2000;

const NO_PRESENCE: Presence = { peers: [], following: undefined };

const storedName = (boardId: string): string =>
  loadRecents(localStorage).find((recent) => recent.id === boardId)?.name ?? boardId;

const clearRenamed = (boardId: string, renamedAt: number): void => {
  const recents = loadRecents(localStorage).map((recent) =>
    recent.id === boardId && recent.renamedAt === renamedAt ? { ...recent, renamedAt: 0 } : recent,
  );
  saveRecents(localStorage, recents);
};

const historyKey = (event: KeyboardEvent): "Undo" | "Redo" | undefined => {
  if (!(event.ctrlKey || event.metaKey) || event.altKey) return undefined;
  const key = event.key.toLowerCase();
  if (key === "z") return event.shiftKey ? "Redo" : "Undo";
  if (key === "y" && !event.shiftKey) return "Redo";
  return undefined;
};

const SURFACE_CLASS: Record<ToolMode, string> = {
  Pencil: "surface",
  Shape: "surface",
  Sticky: "surface",
  Text: "surface",
  Pan: "surface panning",
  Eraser: "surface erasing",
  Select: "surface selecting",
};

export function Board({ boardId }: { boardId: string }) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [tool, setTool] = useState<Tool>({
    width: PENCIL_PX.Medium,
    style: loadStyle(() => localStorage),
    primary: PALETTE_RGB[0],
    secondary: PALETTE_RGB[4],
    shape: "Rectangle",
    fill: "None",
    mode: "Pencil",
  });
  const [error, setError] = useState<string | undefined>(undefined);
  const [connection, setConnection] = useState<Connection>("LocalOnly");
  const [history, setHistory] = useState<HistoryState>(EMPTY_HISTORY);
  const [view, setView] = useState<SurfaceView>(INITIAL_VIEW);
  const [shareOpen, setShareOpen] = useState(false);
  const [presence, setPresence] = useState<Presence>(NO_PRESENCE);
  const [name, setName] = useState(() => storedName(boardId));
  const [edit, setEdit] = useState<TextEdit | undefined>(undefined);
  const editorRef = useRef<HTMLTextAreaElement>(null);
  const editRef = useRef<TextEdit | undefined>(undefined);
  const onEdit = useCallback((next: TextEdit | undefined) => {
    const previous = editRef.current;
    editRef.current = next;
    if (next && next.objectId !== previous?.objectId) openEditor(editorRef.current, next.text);
    if (!next && previous) editorRef.current?.blur();
    setEdit(next);
  }, []);
  const editText = useCallback((text: string) => surfaceRef.current?.editText(text), []);
  const finishEdit = useCallback(() => surfaceRef.current?.finishEdit(), []);
  const panBy = useCallback((dx: number, dy: number) => surfaceRef.current?.panBy(dx, dy), []);
  const sourceRef = useRef<BoardSource | undefined>(undefined);
  const surfaceRef = useRef<Surface | undefined>(undefined);
  const [levels] = useState<LevelBrowser>(() => ({
    levelObjects: (level) => surfaceRef.current?.levelObjects(level) ?? { items: [], more: 0 },
    preview: (objectId) => surfaceRef.current?.preview(objectId),
    jumpTo: (objectId) => surfaceRef.current?.jumpTo(objectId),
    highlight: (objectId) => surfaceRef.current?.highlight(objectId),
  }));
  const toolRef = useRef(tool);
  toolRef.current = tool;
  const closeShare = useCallback(() => setShareOpen(false), []);
  const checkAuthExpired = useCallback(async () => {
    const result = await myBoardsForPage()?.list();
    return (
      result !== undefined &&
      !result.ok &&
      (result.reason === "AuthRedirect" ||
        result.reason === "Http401" ||
        result.reason === "Http403")
    );
  }, []);
  const notice = useConnectionNotice(connection, checkAuthExpired);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const openedAt = Date.now();
    saveRecents(
      localStorage,
      upsertRecent(loadRecents(localStorage), { id: boardId, lastOpened: openedAt }),
    );
    const api = myBoardsForPage();
    let live = true;
    void api?.upsert(boardId, { lastOpened: openedAt }).then((result) => {
      if (!live || !result.ok) return;
      const local = loadRecents(localStorage).find((recent) => recent.id === boardId);
      if (local?.renamedAt !== 0 || local.name === result.value.name) return;
      saveRecents(
        localStorage,
        upsertRecent(loadRecents(localStorage), {
          id: boardId,
          name: result.value.name,
          lastOpened: local.lastOpened,
        }),
      );
      setName(result.value.name);
    });
    const uploads = thumbnailUploader((thumbnail) => {
      void api?.upsert(boardId, { thumbnail });
    });
    const source = openSource({
      url: syncUrlFor(import.meta.env.VITE_SYNC_URL, window.location),
      boardId,
      openBoard,
      onConnection: setConnection,
      onError: setError,
    });
    sourceRef.current = source;
    const syncHistory = () =>
      setHistory({ canUndo: source.history.canUndo, canRedo: source.history.canRedo });
    const unobserve = source.history.observe(syncHistory);
    const onKey = (event: KeyboardEvent) => {
      if (event.target instanceof HTMLInputElement || event.target instanceof HTMLTextAreaElement)
        return;
      const action = historyKey(event);
      if (!action) return;
      event.preventDefault();
      if (action === "Undo") source.history.undo();
      else source.history.redo();
    };
    window.addEventListener("keydown", onKey);
    let thumbnailTimer: ReturnType<typeof setTimeout> | undefined;
    const saveThumbnail = () => {
      thumbnailTimer = undefined;
      const thumbnail = captureThumbnail(canvas);
      if (!thumbnail) return;
      saveRecents(
        localStorage,
        upsertRecent(loadRecents(localStorage), { id: boardId, thumbnail }),
      );
      uploads.push(thumbnail);
    };
    const scheduleThumbnail = () => {
      clearTimeout(thumbnailTimer);
      thumbnailTimer = setTimeout(saveThumbnail, THUMBNAIL_DELAY_MS);
    };
    let surface: Surface | undefined;
    try {
      surface = createSurface(
        canvas,
        boardId,
        source,
        () => toolRef.current,
        setView,
        scheduleThumbnail,
        setPresence,
        onEdit,
      );
      surfaceRef.current = surface;
    } catch (failure) {
      setError(`Could not start the drawing surface: ${errorMessage(failure)}`);
    }
    return () => {
      live = false;
      if (thumbnailTimer !== undefined) {
        clearTimeout(thumbnailTimer);
        saveThumbnail();
      }
      uploads.flush();
      window.removeEventListener("keydown", onKey);
      unobserve();
      sourceRef.current = undefined;
      setHistory(EMPTY_HISTORY);
      setPresence(NO_PRESENCE);
      surface?.finishEdit();
      surfaceRef.current = undefined;
      surface?.dispose();
      source
        .close()
        .catch((failure: unknown) =>
          setError(`Could not close the board: ${errorMessage(failure)}`),
        );
    };
  }, [boardId, onEdit]);

  useEffect(() => {
    const path = boardPath(boardId, name);
    if (window.location.pathname === path) return;
    const { search, hash } = window.location;
    window.history.replaceState(window.history.state, "", `${path}${search}${hash}`);
  }, [boardId, name]);

  const rename = useCallback(
    (next: string) => {
      const renamedAt = Date.now();
      saveRecents(localStorage, renameRecent(loadRecents(localStorage), boardId, next, renamedAt));
      setName(next);
      myBoardsForPage()
        ?.upsert(boardId, { name: next })
        .then((result) => {
          if (!result.ok) {
            setError(`Could not save the board name: ${result.message}`);
            return;
          }
          clearRenamed(boardId, renamedAt);
        });
    },
    [boardId],
  );

  return (
    <main class="board">
      <canvas
        ref={canvasRef}
        class={SURFACE_CLASS[tool.mode]}
        aria-label={`Drawing board ${boardId}`}
      />
      <TextEditor
        edit={edit}
        areaRef={editorRef}
        onInput={editText}
        onDone={finishEdit}
        onPan={panBy}
      />
      <Toolbar
        tool={tool}
        onChange={setTool}
        connection={connection}
        history={history}
        onUndo={() => sourceRef.current?.history.undo()}
        onRedo={() => sourceRef.current?.history.redo()}
        view={view}
        onLevel={(level) => surfaceRef.current?.zoomToLevel(level)}
        levels={levels}
        shareOpen={shareOpen}
        onShare={() => setShareOpen(!shareOpen)}
        presence={presence}
        onFollow={(clientId) => surfaceRef.current?.follow(clientId)}
      />
      <ReconnectNotice
        notice={notice}
        reconnectMessage="Can't reach the board. Your strokes are kept and sent when it reconnects."
      />
      {shareOpen && (
        <SharePanel
          link={boardLink(window.location.origin, boardId, name)}
          name={name}
          onRename={rename}
          source={sourceRef.current}
          onClose={closeShare}
        />
      )}
      {connection === "Locked" && (
        <PinPrompt
          lock={sourceRef.current?.lock}
          onJoin={(pin) =>
            sourceRef.current
              ? sourceRef.current.join(pin)
              : Promise.resolve({ ok: false, reason: "Closed", message: "the board is not open" })
          }
        />
      )}
      {error && notice === "None" && (
        <div class="error" role="alert">
          <p>{error}. Strokes may not be saved; reload to try again.</p>
          <a href={reportLink(error)} target="_blank" rel="noreferrer">
            Report an issue
          </a>
        </div>
      )}
    </main>
  );
}
import { MAX_STICKY_BYTES } from "@stallion/schema";
import type { RefObject } from "preact";
import { useEffect, useLayoutEffect, useRef } from "preact/hooks";
import type { TextEdit } from "./surface";
import { FONT_FAMILY } from "./wrap";

export const KEYBOARD_GAP_PX = 12;

const DONE_ROW_PX = 52;

const OVERLAYS = [".toolbar", ".presence-floater"];

type Band = { top: number; bottom: number };

type Rect = Band & { left: number; right: number };

const covers = (editor: Rect, overlay: Rect): boolean =>
  overlay.right > overlay.left &&
  overlay.bottom > overlay.top &&
  overlay.left < editor.right &&
  editor.left < overlay.right &&
  overlay.top < editor.bottom &&
  editor.top < overlay.bottom;

export const freeBand = (editor: Rect, visible: Band, overlays: readonly Rect[]): Band => {
  const middle = (visible.top + visible.bottom) / 2;
  const hit = overlays.filter((overlay) => covers(editor, overlay));
  const above = hit.filter((overlay) => (overlay.top + overlay.bottom) / 2 < middle);
  const below = hit.filter((overlay) => (overlay.top + overlay.bottom) / 2 >= middle);
  return {
    top: Math.max(visible.top, ...above.map((overlay) => overlay.bottom + KEYBOARD_GAP_PX)),
    bottom: Math.min(visible.bottom, ...below.map((overlay) => overlay.top - KEYBOARD_GAP_PX)),
  };
};

export const revealShift = (top: number, height: number, band: Band): number => {
  const bottom = top + height;
  if (top < band.top) return Math.max(0, Math.min(band.top - top, band.bottom - bottom));
  const overflow = bottom - band.bottom;
  if (overflow <= 0) return 0;
  return -Math.min(overflow, Math.max(0, top - band.top));
};

const overlayRects = (): Rect[] =>
  OVERLAYS.flatMap((selector) => {
    const element = document.querySelector(selector);
    return element ? [element.getBoundingClientRect()] : [];
  });

type TextEditorProps = {
  edit: TextEdit | undefined;
  areaRef: RefObject<HTMLTextAreaElement>;
  onInput: (text: string) => void;
  onDone: () => void;
  onPan: (dx: number, dy: number) => void;
};

export const openEditor = (area: HTMLTextAreaElement | null, text: string): void => {
  if (!area) return;
  area.value = text;
  area.focus({ preventScroll: true });
  const end = area.value.length;
  area.setSelectionRange(end, end);
};

export function TextEditor({ edit, areaRef, onInput, onDone, onPan }: TextEditorProps) {
  const latest = useRef(edit);
  const panned = useRef({ from: edit?.top, by: 0 });
  latest.current = edit;
  if (panned.current.from !== edit?.top) panned.current = { from: edit?.top, by: 0 };

  const grow = () => {
    const area = areaRef.current;
    const current = latest.current;
    if (!area || !current) return;
    area.style.height = `${current.height}px`;
    if (area.scrollHeight > current.height) area.style.height = `${area.scrollHeight}px`;
  };

  const reveal = () => {
    if (window.scrollX !== 0 || window.scrollY !== 0) window.scrollTo(0, 0);
    const viewport = window.visualViewport;
    const current = latest.current;
    if (!viewport || !current) return;
    const height = Math.max(current.height, areaRef.current?.scrollHeight ?? 0) + DONE_ROW_PX;
    const visible = {
      top: viewport.offsetTop + KEYBOARD_GAP_PX,
      bottom: viewport.offsetTop + viewport.height - KEYBOARD_GAP_PX,
    };
    const editor = {
      left: current.left,
      right: current.left + current.width,
      top: current.top + panned.current.by,
      bottom: current.top + panned.current.by + height,
    };
    const shift = revealShift(editor.top, height, freeBand(editor, visible, overlayRects()));
    if (shift === 0) return;
    panned.current.by += shift;
    onPan(0, shift);
  };

  useLayoutEffect(grow);

  const editing = edit?.objectId;
  useEffect(() => {
    if (editing === undefined) return;
    const viewport = window.visualViewport;
    reveal();
    viewport?.addEventListener("resize", reveal);
    viewport?.addEventListener("scroll", reveal);
    window.addEventListener("scroll", reveal);
    return () => {
      viewport?.removeEventListener("resize", reveal);
      viewport?.removeEventListener("scroll", reveal);
      window.removeEventListener("scroll", reveal);
    };
  }, [editing]);

  const style = edit
    ? {
        left: `${edit.left}px`,
        top: `${edit.top}px`,
        width: `${edit.width}px`,
      }
    : undefined;

  return (
    <div class={edit ? "sticky-editor" : "sticky-editor idle"} style={style}>
      <textarea
        ref={areaRef}
        class="sticky-text"
        aria-label={edit?.label ?? "Note text"}
        spellcheck
        maxLength={MAX_STICKY_BYTES}
        tabIndex={edit ? 0 : -1}
        style={
          edit && {
            font: `${edit.fontPx}px ${FONT_FAMILY}`,
            lineHeight: `${edit.lineHeightPx}px`,
            padding: `${edit.padPx}px`,
            color: edit.ink,
            caretColor: edit.ink,
            background: edit.background,
          }
        }
        onInput={(event) => {
          onInput(event.currentTarget.value);
          grow();
          reveal();
        }}
        onBlur={onDone}
        onKeyDown={(event) => {
          if (event.key === "Escape") event.currentTarget.blur();
        }}
      />
      {edit && (
        <button
          type="button"
          class="sticky-done"
          onPointerDown={(event) => event.preventDefault()}
          onMouseDown={(event) => event.preventDefault()}
          onClick={onDone}
        >
          Done
        </button>
      )}
    </div>
  );
}
