export const usePlacement = (
  open: boolean,
  anchorRef: RefObject<HTMLElement>,
  desiredHeight: number,
): Placement | undefined => {
  const [placement, setPlacement] = useState<Placement | undefined>(undefined);

  useLayoutEffect(() => {
