import { join } from "node:path";
import { createRequire } from "node:module";
const root = join(process.env.HOME, "development/stallion-worktrees/texttools");
const require = createRequire(join(root, "package.json"));
const { chromium, devices } = require("playwright");
const { routeAccessHeaders } = await import(join(root, "npm-scripts/env.mjs"));
const ORIGIN = "https://stallion.matthijs-f49.workers.dev";
const OUT = join(process.env.HOME, "development/.tmp/stallion-texttools/shots");
const OLD = process.argv.slice(2);
const errors = [];
const rnd = () => `proof${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`;
const browser = await chromium.launch({ headless: true });

const open = async (name, device, path) => {
  const context = await browser.newContext(device);
  await routeAccessHeaders(context, ORIGIN);
  const page = await context.newPage();
  page.on("console", (m) => m.type() === "error" && errors.push(`${name}: ${m.text()}`));
  page.on("pageerror", (e) => errors.push(`${name}: ${e.message}`));
  await page.goto(`${ORIGIN}${path}`);
  await page.locator("canvas.surface").waitFor();
  await page.waitForTimeout(1500);
  return { context, page, shot: (label) => page.screenshot({ path: join(OUT, `${name}-${label}.png`) }) };
};

const pickTool = async (page, label) => {
  const more = page.getByRole("button", { name: "More tools" });
  if (await more.isVisible()) await more.tap();
  await page.locator("[data-toolbar-flip]").tap();
  await page.waitForTimeout(400);
  await page.locator('.toolbar[data-layout="Palette"]').getByRole("button", { name: label }).tap();
  await page.locator("[data-toolbar-flip]").tap();
  await page.waitForTimeout(300);
  const fewer = page.getByRole("button", { name: "Fewer tools" });
  if (await fewer.isVisible()) await fewer.tap();
  await page.waitForTimeout(300);
};

const touch = async (page, points) => {
  const cdp = await page.context().newCDPSession(page);
  const send = (type, p) =>
    cdp.send("Input.dispatchTouchEvent", { type, touchPoints: p ? [{ x: p.x, y: p.y }] : [] });
  await send("touchStart", points[0]);
  for (const p of points.slice(1)) {
    await send("touchMove", p);
    await page.waitForTimeout(16);
  }
  await send("touchEnd");
  await cdp.detach();
};

const line = (from, to, steps = 20) =>
  Array.from({ length: steps + 1 }, (_, i) => ({
    x: from.x + ((to.x - from.x) * i) / steps,
    y: from.y + ((to.y - from.y) * i) / steps,
  }));

const toolbar = (page) => page.getByRole("toolbar", { name: /^(Text|Note text)$/ });
const editor = (page) => page.locator(".sticky-editor:not(.idle) textarea");
const done = async (page) => {
  await page.getByRole("button", { name: "Done" }).tap();
  await page.waitForTimeout(600);
};

const placeText = async (page, at, text) => {
  await touch(page, [at]);
  await editor(page).waitFor();
  await page.keyboard.type(text);
  await page.waitForTimeout(300);
};

for (const [name, device] of [
  ["phone", devices["Pixel 7"]],
  ["tablet", devices["Galaxy Tab S9"]],
  ["desktop", { viewport: { width: 1440, height: 900 }, hasTouch: true }],
]) {
  const { context, page, shot } = await open(name, device, `/b/${rnd()}`);
  await pickTool(page, "Text tool");
  const vp = page.viewportSize();
  const at = { x: Math.round(vp.width / 2 - 140), y: Math.round(vp.height * 0.4) };
  await placeText(page, at, "Text toolbar");
  await shot("toolbar-editing");
  if (name === "tablet") {
    for (const font of ["Sans", "Serif", "Mono", "Hand"]) {
      await toolbar(page).getByRole("button", { name: /^Font: / }).tap();
      await page.waitForTimeout(200);
      if (font === "Serif") await shot("font-menu");
      await toolbar(page).getByRole("button", { name: `${font} font` }).tap();
      await page.waitForTimeout(300);
      await done(page);
      await shot(`font-${font.toLowerCase()}`);
      await touch(page, [{ x: at.x + 10, y: at.y }]);
      await editor(page).waitFor();
    }
    await toolbar(page).getByRole("button", { name: "Bold", exact: true }).tap();
    await toolbar(page).getByRole("button", { name: "Italic", exact: true }).tap();
    await page.waitForTimeout(300);
    await shot("bold-italic-editing");
    await done(page);
    await shot("bold-italic");
    await touch(page, [{ x: at.x + 10, y: at.y }]);
    await editor(page).waitFor();
    await toolbar(page).getByRole("button", { name: "Link", exact: true }).tap();
    await toolbar(page).getByLabel("Link address").fill("example.com/stallion");
    await shot("link-field");
    await toolbar(page).getByRole("button", { name: "Save" }).tap();
    await page.waitForTimeout(600);
    await page.mouse.click(5, vp.height - 5);
    await pickTool(page, "Pan tool");
    await shot("linked");

    await pickTool(page, "Text tool");
    const tat = { x: 60, y: Math.round(vp.height * 0.62) };
    await placeText(page, tat, "Auto fit text box");
    await toolbar(page).getByRole("button", { name: "Fit text to the frame" }).tap();
    await page.waitForTimeout(400);
    await done(page);
    await pickTool(page, "Select tool");
    await touch(page, [{ x: tat.x + 20, y: tat.y }]);
    await editor(page).waitFor();
    const tbox = await editor(page).boundingBox();
    await shot("auto-text-before");
    await done(page);
    const tcorner = { x: tbox.x + tbox.width + 4, y: tbox.y + tbox.height + 4 };
    await touch(page, line(tcorner, { x: tcorner.x - tbox.width * 0.4, y: tcorner.y + tbox.height * 1.6 }));
    await page.waitForTimeout(600);
    await shot("auto-text-resized");

    await pickTool(page, "Sticky note");
    const sat = { x: Math.round(vp.width * 0.75), y: Math.round(vp.height * 0.25) };
    await touch(page, [sat]);
    await editor(page).waitFor();
    await page.keyboard.type("Auto fit note");
    await toolbar(page).getByRole("button", { name: "Fit text to the frame" }).tap();
    await page.waitForTimeout(400);
    await shot("auto-sticky-editing");
    const sbox = await editor(page).boundingBox();
    await done(page);
    await pickTool(page, "Select tool");
    await touch(page, [{ x: sbox.x + 10, y: sbox.y + 10 }]);
    await editor(page).waitFor();
    await done(page);
    await shot("auto-sticky-before");
    const scorner = { x: sbox.x + sbox.width + 4, y: sbox.y + sbox.height + 4 };
    await touch(page, line(scorner, { x: scorner.x + 150, y: scorner.y + 120 }));
    await page.waitForTimeout(600);
    await shot("auto-sticky-resized");
  }
  await context.close();
}

for (const board of ["cagl5toewxf62ts2fn43id996", ...OLD]) {
  const { context, shot } = await open(`old-${board}`, devices["Galaxy Tab S9"], `/b/${board}`);
  await shot("render");
  await context.close();
}
await browser.close();
console.log("errors", JSON.stringify(errors));
EOF
